"""Science, Year 7 (KS3).

KS3 science is one programme of study for Years 7 to 9. The split agreed for this app puts these in
Year 7 (one skill per statutory statement; broad statements are split into the lessons a teacher would
teach):

* Working scientifically: hypotheses and predictions; independent, dependent and control variables and
  fair tests; SI units and prefixes (milli-, centi-, kilo-); repeat readings, means, anomalous results,
  accuracy and precision (simply); tables, bar charts and line graphs; hazards and risks.
* Cells and organisation: cells and the light microscope (magnification = image size / actual size);
  functions of cell parts; plant and animal cells; diffusion into and out of cells; unicellular organisms
  (amoeba, euglena, yeast); specialised cells; cells -> tissues -> organs -> organ systems -> organisms.
* Skeletal and muscular systems: the skeleton; muscles and antagonistic pairs; joints and biomechanics,
  including measuring the force exerted by different muscles.
* Reproduction: human reproductive systems; gametes and the menstrual cycle (no hormones); fertilisation
  and gestation; the placenta, maternal lifestyle and birth; flower structure; wind and insect
  pollination; fertilisation, seeds and fruits; seed dispersal, including quantitative investigation.
* Particles: states of matter in the particle model; gas pressure; changes of state; melting and boiling
  points; diffusion in liquids and gases; Brownian motion (simply, shared with diffusion).
* Mixtures and separation: pure substances and mixtures (sharp melting point); dissolving and
  solubility; filtration and evaporation; distillation; chromatography.
* Acids and alkalis: the pH scale and indicators; neutralisation; acid + alkali -> salt + water, naming
  chlorides, sulfates and nitrates.
* Forces: pushes and pulls between two objects, force arrows (described in words), newtons; resultant
  force, balanced and unbalanced forces, equilibrium; friction; air and water resistance; stretching and
  squashing, work done and energy on deformation; Hooke's law; mass and weight (W = m x g, g = 10 N/kg on
  Earth); gravity in space and on other planets.
* Sound: vibrations, the medium and the speed of sound; longitudinal waves, loudspeakers, microphones and
  the ear; frequency (Hz) and pitch, amplitude and loudness; hearing ranges and ultrasound; echoes,
  reflection and absorption.
* Space physics: the Sun as a star, galaxies and the light year; seasons, the Earth's tilt and day length;
  the phases of the Moon.

Moments (turning effect of a force) are left for Year 9, as agreed. All other KS3 statements belong to
Years 8 and 9.
"""

